package com.emos.notifications.infrastructure;
import com.emos.notifications.application.DigestDeliveryStore;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;import java.sql.Timestamp;import java.time.*;import java.util.UUID;
@Repository @ConditionalOnProperty(name="emos.email.enabled",havingValue="true") public class JdbcDigestDeliveryStore implements DigestDeliveryStore{private final JdbcTemplate jdbc;public JdbcDigestDeliveryStore(JdbcTemplate jdbc){this.jdbc=jdbc;}public boolean wasSent(LocalDate d,String r){return Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from notification_delivery where local_date=? and recipient=? and status='SENT')",Boolean.class,d,r));}public void sent(LocalDate d,String r,Instant at){upsert(d,r,"SENT",at,null);}public void failed(LocalDate d,String r,Instant at,String message){upsert(d,r,"FAILED",at,message);}private void upsert(LocalDate d,String r,String status,Instant at,String error){jdbc.update("insert into notification_delivery(id,local_date,recipient,status,attempted_at,error_message) values(?,?,?,?,?,?) on conflict(local_date,recipient) do update set status=excluded.status,attempted_at=excluded.attempted_at,error_message=excluded.error_message",UUID.randomUUID(),d,r,status,Timestamp.from(at),error);}}
